# Generate 102 technical farms and 30+ technical dupers/glitches
$repoRoot = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
$dbFile = Join-Path $repoRoot "data\database.json"
$db = Get-Content -Raw -Encoding utf8 $dbFile | ConvertFrom-Json

# Run expand_gear first
. (Join-Path $PSScriptRoot "expand_gear.ps1")

# Function to create farm entry
function New-Farm {
    param(
        $id, $category, $tier, $title_es_mx, $title_en, $rate, $desc, $schematic, $tips,
        $materials, $author, $tutorial_title, $url, $diagram
    )
    [PSCustomObject]@{
        id = $id
        category = $category
        tier = $tier
        title_es_mx = $title_es_mx
        title_en = $title_en
        rate = $rate
        desc = $desc
        schematic = $schematic
        tips = $tips
        materials = $materials
        tutorial_author = $author
        tutorial_title = $tutorial_title
        tutorial_url = $url
        diagram = $diagram
    }
}

# Function to create dupe entry
function New-Dupe {
    param(
        $id, $category, $title, $status, $difficulty, $components, $materials, $how_it_works, $use_cases,
        $author, $tutorial_title, $url, $diagram
    )
    [PSCustomObject]@{
        id = $id
        category = $category
        title = $title
        status = $status
        difficulty = $difficulty
        components = $components
        materials = $materials
        how_it_works = $how_it_works
        use_cases = $use_cases
        tutorial_author = $author
        tutorial_title = $tutorial_title
        tutorial_url = $url
        diagram = $diagram
    }
}

$farmsList = [System.Collections.Generic.List[PSCustomObject]]::new()
$dupesList = [System.Collections.Generic.List[PSCustomObject]]::new()

# Keep initial base farms
foreach ($f in $db.farms) { 
    if ($farmsList.Count -lt 12) {
        $farmsList.Add($f) 
    }
}

