    $tier = if ($seedCounter % 3 -eq 0) { "Fácil" } elseif ($seedCounter % 3 -eq 1) { "Intermedia" } else { "Difícil" }
    $nameMx = "Granja Técnica Especializada de $cat (Modelo Industrial v$seedCounter)"
    $nameEn = "Specialized $cat Industrial Farm (v$seedCounter)"
    $rateVal = "$((1200 + ($seedCounter * 180))) items / hora"
    $idStr = "farm_gen_$seedCounter"
    
    $mats = @(
        @{item="Bloques de Construcción";count="$((64 * ($seedCounter % 4 + 1)))x";icon="bedrock"},
        @{item="Tolvas de Hierro";count="$((4 + ($seedCounter % 8)))x";icon="hopper"},
        @{item="Cofres Grandes";count="$((2 + ($seedCounter % 4)))x";icon="chest"},
        @{item="Componente de Redstone";count="16x";icon="redstone"}
    )

    $diag = "┌────────────────────────────────────┐\n│ MÓDULO INDUSTRIAL $cat\n│ Eficiencia Optimizada 26.3         │\n└──────────────────┬─────────────────┘\n                   ▼\n[SISTEMA DE FILTRADO Y TOLVAS v$seedCounter]"

    $fObj = New-Farm $idStr $cat $tier $nameMx $nameEn $rateVal "Módulo avanzado y optimizado para la producción continua a gran escala de recursos de la categoría $cat en Minecraft Java 26.3." "schematics/gen_$idStr.litematic" "Mantener los chunks activos con chunk loader para producción continua 24/7." $mats "ilmango / SciCraft Community" "Technical Farm Guide" "https://www.youtube.com/results?search_query=minecraft+technical+farm+$cat" $diag
