foreach ($d in $curatedDupes) {
    $dupesList.Add($d)
}

# Assign lists to database
$db.farms = $farmsList
$db.dupes = $dupesList

# Convert to JSON with high depth
$jsonStr = $db | ConvertTo-Json -Depth 15
[System.IO.File]::WriteAllText($dbFile, $jsonStr, [System.Text.Encoding]::UTF8)

# Also copy to target/release/data/database.json
$targetData = Join-Path $repoRoot "target\release\data"
if (-not (Test-Path $targetData)) { New-Item -ItemType Directory -Path $targetData -Force | Out-Null }
[System.IO.File]::WriteAllText("$targetData\database.json", $jsonStr, [System.Text.Encoding]::UTF8)

Write-Host "Database generated successfully!"
Write-Host "Total Gear items: $($db.gear.Count)"
Write-Host "Total Technical Farms: $($db.farms.Count) (Target: 100+)"
Write-Host "Total Exploits & Dupers: $($db.dupes.Count)"
